} else if (subcommand === 'cursor') {
  try {
    const { runAcp } = await import('@/agent/acp/runAcp');
    const { cursorTransport } = await import('@/agent/transport');
    const { execSync } = await import('node:child_process');
    const { existsSync } = await import('node:fs');

    let startedBy: 'daemon' | 'terminal' | undefined = undefined;
    for (let i = 1; i < args.length; i++) {
      if (args[i] === '--started-by') {
        startedBy = args[++i] as 'daemon' | 'terminal';
      }
    }

    const { credentials } = await authAndSetupMachineIfNeeded();

    logger.debug('Ensuring Happy background service is running & matches our version...');
    if (!(await isDaemonRunningCurrentlyInstalledHappyVersion())) {
      logger.debug('Starting Happy background service...');
      const daemonProcess = spawnHappyCLI(['daemon', 'start-sync'], {
        detached: true,
        stdio: 'ignore',
        env: process.env
      });
      daemonProcess.unref();
      await new Promise(resolve => setTimeout(resolve, 200));
    }

    // Resolve cursor-agent binary path
    let cursorAgentPath = process.env.CURSOR_AGENT_PATH || '';
    if (!cursorAgentPath) {
      try {
        cursorAgentPath = execSync('which cursor-agent', { encoding: 'utf8' }).trim();
      } catch {
        const fallbacks = ['/opt/homebrew/bin/cursor-agent', '/usr/local/bin/cursor-agent'];
        cursorAgentPath = fallbacks.find(p => existsSync(p)) ?? 'cursor-agent';
      }
    }
    logger.debug(`[cursor] Using cursor-agent at: ${cursorAgentPath}`);

    await runAcp({
      credentials,
      agentName: 'cursor',
      command: cursorAgentPath,
      args: ['acp'],
      startedBy,
      transportHandler: cursorTransport,
    });
  } catch (error) {
    console.error(chalk.red('Error:'), error instanceof Error ? error.message : 'Unknown error');
    if (process.env.DEBUG) {
      console.error(error);
    }
    process.exit(1);
  }
  return;
